			// irradiance are read, so both lookups take the halved variants
			// (same values, see GetSkyTransmittance / GetSkyIrradianceLum).
			sky_transmittance = GetSkyTransmittance(
				atm, transmittanceTex, pos - ctx.earthCenter, ctx.sunDir);
			skyIrradiance = GetSkyIrradianceLum(atm, irradianceTex,
				pos - ctx.earthCenter, normalize(pos - ctx.earthCenter), ctx.sunDir);
